import json

def _safe(v, default=None):
    if v is None:
        return default
    # numpy scalar → Python native
    if hasattr(v, 'item'):
        try:
            return v.item()
        except Exception:
            return default
    if hasattr(v, 'tolist'):
        return v.tolist()
    return v

results = {
    'control_n':   _safe(globals().get('control_n')),
    'treatment_n': _safe(globals().get('treatment_n')),
    'delta_rel':   _safe(globals().get('delta_rel')),
    'p_value':     _safe(globals().get('p_value')),
    'ci_lower':    _safe(globals().get('ci_lower')),
    'ci_upper':    _safe(globals().get('ci_upper')),
    'control_mean': _safe(globals().get('control_mean')),
    'srm_pvalue':  _safe(globals().get('srm_pvalue')),
    'novelty_flag': _safe(globals().get('novelty_flag'), None),
    'guardrails':  _safe(globals().get('guardrail_results'), []),
}
_pv = _safe(globals().get('p_value'))
_alpha = _safe(globals().get('alpha'), 0.05)
results['significant'] = bool(_pv is not None and _pv < _alpha)
print(json.dumps(results, indent=2, default=str))
